package school.magiccodex.paper;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import school.magiccodex.database.DatabaseSettings;import school.magiccodex.protocol.SocialProtocol;import static org.junit.jupiter.api.Assertions.*;
/** Isolated fixtures reproduce a shared housing DB that has no authoritative social/nickname rows. */
class HousingAuthorityReadTest {
 @TempDir Path temp;
 @Test void separateHousingCacheCannotHideAuthoritativeFriendOrExposeHistoricalAccount()throws Exception{var owner=UUID.randomUUID();var target=UUID.randomUUID();var settings=new DatabaseSettings(false,"","","");try(var friends=new FriendStore(temp.resolve("general-friends.db"));var names=new NicknameStore(temp.resolve("registered-names.db"),settings);var unrelatedHousing=new FriendStore(temp.resolve("housing-db.db"))){assertTrue(friends.add(owner,new SocialProtocol.Entry(target,"EnglishAccount","lumina",false)));names.save(target,"EnglishAccount","황준우",0);assertTrue(unrelatedHousing.load(owner).isEmpty());var ids=friends.load(owner).stream().map(SocialProtocol.Entry::id).toList();assertEquals(List.of(target),ids);assertEquals("황준우",names.load(ids.getFirst()).nickname());names.save(target,"EnglishAccount","바뀐닉",1);assertEquals("바뀐닉",names.load(ids.getFirst()).nickname());assertEquals("EnglishAccount",friends.load(owner).getFirst().name(),"read path preserves old cached relation rows");assertEquals(List.of(target),friends.load(owner).stream().map(SocialProtocol.Entry::id).toList());assertTrue(unrelatedHousing.load(owner).isEmpty());}}
}
